"use client";

import Link from "next/link";
import dynamic from "next/dynamic";
import { usePathname, useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import type { FormEvent, ReactNode } from "react";
import type { Actor, Currency } from "../../lib/travel";
import { formatMoney } from "../../lib/travel";
import type { WorkspaceArea } from "./Workspace";

type WorkspaceValue = string | number | boolean | null | undefined;
type Row = {
  [key: string]: WorkspaceValue;
  id?: string;
  status?: string;
  role?: string;
  type?: string;
  kind?: string;
  currency?: string;
  organization_id?: string | null;
  user_id?: string | null;
  request_number?: string;
  quote_number?: string;
  booking_number?: string;
  invoice_number?: string;
  ticket_number?: string;
  destination?: string;
  title?: string;
  subject?: string;
  created_at?: number | string;
  updated_at?: number | string;
};
export type WorkspacePayload = { requests: Row[]; quotes: Row[]; bookings: Row[]; invoices: Row[]; tickets: Row[]; approvals: Row[]; assignments: Row[]; leads?: Row[]; users?: Row[]; organizations?: Row[]; suppliers?: Row[]; content?: Row[]; notifications?: Row[]; activity?: Row[]; members?: Row[]; organization?: Row | null; report?: { pipeline: Row[]; finance: Row[]; totals: Row };overview?:{metrics:Row;recent:Row[]} };

const QuoteRouteView=dynamic(()=>import("./workspace/QuoteRouteView").then((module)=>module.QuoteRouteView),{loading:()=> <div className="workspace-empty">Loading proposals…</div>});
const FinanceRouteView=dynamic(()=>import("./workspace/FinanceRouteView").then((module)=>module.FinanceRouteView),{loading:()=> <div className="workspace-empty">Loading finance…</div>});
const SupportRouteView=dynamic(()=>import("./workspace/SupportRouteView").then((module)=>module.SupportRouteView),{loading:()=> <div className="workspace-empty">Loading support…</div>});
const ContentRouteView=dynamic(()=>import("./workspace/ContentRouteView").then((module)=>module.ContentRouteView),{loading:()=> <div className="workspace-empty">Loading content tools…</div>});

export function WorkspaceView({ area, view, actor, data }: { area: WorkspaceArea; view: string; actor: Actor; data: WorkspacePayload }) {
  if (!view) return <Overview area={area} data={data} />;
  if (["requests","pipeline"].includes(view)) return area === "staff" ? <RequestOperations rows={data.requests} /> : <RequestsView rows={data.requests} staff={false} />;
  if (view === "quotes") return <QuoteRouteView rows={data.quotes} requests={data.requests} staff={area === "staff"} />;
  if (view === "bookings") return area === "staff" ? <BookingOperations rows={data.bookings} /> : <BookingsView rows={data.bookings} staff={false} />;
  if (["invoices","finance"].includes(view)) return <FinanceRouteView invoices={data.invoices} bookings={data.bookings} staff={area === "staff"} actor={actor} />;
  if (view === "support") return <SupportRouteView rows={data.tickets} bookings={data.bookings} staff={area === "staff"} />;
  if (view === "leads") return <LeadInbox rows={data.leads ?? []} />;
  if (view === "approvals") return <ApprovalsView rows={data.approvals} />;
  if (view === "assignments") return <AssignmentsView rows={data.assignments} />;
  if (view === "documents") return <DocumentsView data={data} />;
  if (["users","travelers"].includes(view)) return area === "staff" ? <UserAdministration rows={data.users ?? []} organizations={data.organizations ?? []} /> : <UsersView rows={data.members ?? []} staff={false} />;
  if (view === "companies") return <OrganizationManager rows={data.organizations ?? []} />;
  if (view === "partners") return <PartnerManager suppliers={data.suppliers ?? []} organizations={data.organizations ?? []} bookings={data.bookings} assignments={data.assignments} />;
  if (view === "content") return <ContentRouteView rows={data.content ?? []} />;
  if (view === "notifications") return <NotificationOutbox rows={data.notifications ?? []} />;
  if (view === "audit") return <ActivityView rows={data.activity ?? []} />;
  if (view === "reports") return <ReportsView data={data} />;
  if (["settings","profile"].includes(view)) return <SettingsView actor={actor} organization={data.organization} area={area} />;
  return <EmptyState title="This workspace view is ready" text="There are no records to show yet." />;
}

const requestNext: Record<string, string[]> = { submitted:["qualified","closed"], qualified:["quoting","closed"], quoting:["quoted","closed"], quoted:["approved","declined","quoting"], approved:["converted"], declined:["quoting","closed"] };
const bookingNext: Record<string, string[]> = { pending:["confirmed","cancelled"], confirmed:["in_progress","cancelled"], in_progress:["completed","cancelled"] };
const mutationHeaders = (idempotent = false) => ({ "Content-Type": "application/json", ...(idempotent ? { "Idempotency-Key": crypto.randomUUID() } : {}) });

function LeadInbox({ rows }: { rows: Row[] }) {
  const router=useRouter();const[query,setQuery]=useState("");const[selected,setSelected]=useState<Row|null>(null);const[message,setMessage]=useState("");
  const visible=rows.filter((row)=>rowMatches(row,query));
  const update=async(id:string,status:string)=>{setMessage("");const response=await fetch(`/api/staff/leads/${id}`,{method:"PATCH",headers:mutationHeaders(),body:JSON.stringify({status})});const payload=await response.json() as{error?:string};setMessage(response.ok?"Lead updated.":payload.error||"Could not update lead");if(response.ok)router.refresh();};
  const convert=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(!selected)return;const form=new FormData(event.currentTarget);const response=await fetch(`/api/staff/leads/${selected.id}/convert`,{method:"POST",headers:mutationHeaders(true),body:JSON.stringify({kind:form.get("kind"),origin:form.get("origin"),destination:form.get("destination"),departureDate:form.get("departureDate"),returnDate:form.get("returnDate"),travelerCount:Number(form.get("travelerCount")),budgetMinor:Math.round(Number(form.get("budget")||0)*100),currency:form.get("currency"),interests:[],notes:form.get("notes")})});const payload=await response.json() as{error?:string};setMessage(response.ok?"Lead converted to a travel request.":payload.error||"Could not convert lead");if(response.ok){setSelected(null);router.refresh();}};
  return <div className="workspace-stack"><section className="workspace-panel"><PanelHeading title="Lead inbox"/><TableTools query={query} setQuery={setQuery} count={visible.length}/>{message&&<p className="workspace-message">{message}</p>}<div className="workspace-table"><div className="workspace-table-head"><span>Contact</span><span>Interest</span><span>Message</span><span>Status</span><span>Next step</span></div>{visible.map((row)=><div className="workspace-table-row" key={String(row.id)}><strong>{String(row.name)}<small>{String(row.email)}</small></strong><span>{String(row.type)}</span><span>{String(row.message).slice(0,120)}</span><Status value={String(row.status)}/><div className="quote-actions"><select aria-label={`Update ${row.name}`} value="" onChange={(event)=>event.target.value&&update(String(row.id),event.target.value)}><option value="">Update</option><option value="contacted">Contacted</option><option value="qualified">Qualified</option><option value="closed">Closed</option></select>{row.status!=="converted"&&row.status!=="closed"&&<button onClick={()=>setSelected(row)}>Convert</button>}</div></div>)}</div>{visible.length===0&&<EmptyState title="No leads yet" text="Website enquiries will appear here for follow-up."/>}</section>{selected&&<form className="workspace-form" onSubmit={convert}><PanelHeading title={`Convert ${String(selected.name)}`} action={<button type="button" onClick={()=>setSelected(null)}>Close</button>}/><div className="workspace-form-grid"><label>Journey type<select name="kind"><option value="personal">Personal</option><option value="corporate">Corporate</option><option value="event">Event</option></select></label><label>Origin<input name="origin" defaultValue="Nairobi" required/></label><label>Destination<input name="destination" required/></label><label>Departure<input type="date" name="departureDate" min={new Date().toISOString().slice(0,10)} required/></label><label>Return<input type="date" name="returnDate" min={new Date().toISOString().slice(0,10)} required/></label><label>Travelers<input type="number" name="travelerCount" min="1" defaultValue="1" required/></label><label>Budget<input type="number" name="budget" min="0" defaultValue="0"/></label><label>Currency<select name="currency"><option>KES</option><option>USD</option></select></label><label className="wide">Notes<textarea name="notes" defaultValue={String(selected.message||"")}/></label></div><button className="pill primary">Create travel request</button></form>}</div>;
}

function RequestOperations({ rows }: { rows: Row[] }) {
  const router=useRouter(); const[query,setQuery]=useState(""); const[error,setError]=useState("");
  const visible=rows.filter((row)=>rowMatches(row,query));
  const change=async(id:string,status:string)=>{setError("");const response=await fetch(`/api/trip-requests/${id}/status`,{method:"PATCH",headers:mutationHeaders(true),body:JSON.stringify({status})});const payload=await response.json() as{error?:string};if(!response.ok)return setError(payload.error||"Could not update request");router.refresh();};
  return <section className="workspace-panel"><PanelHeading title="Travel request pipeline" action={<Link className="pill primary compact" href="/plan-a-trip">New request</Link>}/><TableTools query={query} setQuery={setQuery} count={visible.length}/>{error&&<p className="workspace-error">{error}</p>}<div className="workspace-table"><div className="workspace-table-head"><span>Reference</span><span>Journey</span><span>Traveler</span><span>Status</span><span>Next step</span></div>{visible.map((row)=><div className="workspace-table-row" key={String(row.id)}><strong>{String(row.request_number)}</strong><span>{String(row.origin)} → {String(row.destination)}<small>{String(row.departure_date)} to {String(row.return_date)}</small></span><span>{String(row.contact_name)}<small>{String(row.contact_email)}</small></span><Status value={String(row.status)}/><select aria-label={`Update ${row.request_number}`} defaultValue="" onChange={(event)=>event.target.value&&change(String(row.id),event.target.value)}><option value="">Choose action</option>{(requestNext[String(row.status)]||[]).map((status)=><option key={status} value={status}>{status.replaceAll("_"," ")}</option>)}</select></div>)}</div>{visible.length===0&&<EmptyState title="No requests yet" text="New concierge briefs will appear here."/>}</section>;
}

function BookingOperations({ rows }: { rows: Row[] }) {
  const router=useRouter(); const[editing,setEditing]=useState(""); const[error,setError]=useState("");
  const change=async(id:string,status:string)=>{const response=await fetch(`/api/bookings/${id}/status`,{method:"PATCH",headers:mutationHeaders(true),body:JSON.stringify({status})});const payload=await response.json() as{error?:string};if(!response.ok)return setError(payload.error||"Could not update booking");router.refresh();};
  const itinerary=async(e:FormEvent<HTMLFormElement>,id:string)=>{e.preventDefault();const form=new FormData(e.currentTarget);const response=await fetch(`/api/bookings/${id}/itinerary`,{method:"POST",headers:mutationHeaders(true),body:JSON.stringify({dayNumber:Number(form.get("dayNumber")),date:form.get("date"),title:form.get("title"),location:form.get("location"),description:form.get("description")})});const payload=await response.json() as{error?:string};if(!response.ok)return setError(payload.error||"Could not save itinerary day");setEditing("");router.refresh();};
  return <section className="workspace-panel"><PanelHeading title="Booking operations"/>{error&&<p className="workspace-error">{error}</p>}<div className="booking-grid">{rows.map((row)=><article key={String(row.id)}><small>{String(row.booking_number)}</small><h3>{String(row.destination)}</h3><p>{String(row.departure_date)} → {String(row.return_date)}</p><div><Status value={String(row.status)}/><span>{String(row.traveler_count)} travelers</span></div><div className="quote-actions">{(bookingNext[String(row.status)]||[]).map((status)=><button className={status==="cancelled"?"danger":""} key={status} onClick={()=>change(String(row.id),status)}>{status.replaceAll("_"," ")}</button>)}<button onClick={()=>setEditing(editing===row.id?"":String(row.id))}>Add itinerary day</button>{row.itinerary_pdf_key&&<a href={`/api/documents/booking/${row.id}`}>Itinerary PDF</a>}</div>{editing===row.id&&<form className="payment-form" onSubmit={(event)=>itinerary(event,String(row.id))}><input name="dayNumber" type="number" min="1" placeholder="Day" required/><input name="date" type="date" required/><input name="title" placeholder="Day title" required/><input name="location" placeholder="Location"/><textarea name="description" placeholder="Service and experience details"/><button>Save day</button></form>}</article>)}</div>{rows.length===0&&<EmptyState title="No bookings yet" text="Approved quotes become operational bookings here."/>}</section>;
}

function UserAdministration({ rows, organizations }: { rows:Row[]; organizations:Row[] }) {
  const router=useRouter();const[open,setOpen]=useState(false);const[message,setMessage]=useState("");
  const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);const organizationId=String(form.get("organizationId")||"");const response=await fetch("/api/staff/users",{method:"POST",headers:mutationHeaders(true),body:JSON.stringify({email:form.get("email"),fullName:form.get("fullName"),role:form.get("role"),organizationId:organizationId||undefined})});const payload=await response.json() as{error?:string};setMessage(response.ok?"Invitation created.":payload.error||"Could not invite user");if(response.ok){setOpen(false);router.refresh();}};
  return <div className="workspace-stack"><button className="workspace-create-card" onClick={()=>setOpen(!open)}><span>＋</span><div><strong>Invite a user</strong><small>Assign a staff, company or partner role</small></div></button>{open&&<form className="workspace-form user-invite-form" onSubmit={submit}><label>Full name<input name="fullName" required/></label><label>Email<input type="email" name="email" required/></label><label>Role<select name="role"><option value="agent">Travel agent</option><option value="finance">Finance</option><option value="content">Content</option><option value="admin">Administrator</option><option value="corporate_requester">Corporate requester</option><option value="corporate_approver">Corporate approver</option><option value="partner">Partner</option></select></label><label>Organization<select name="organizationId"><option value="">TVSE staff / none</option>{organizations.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.name)} · {String(row.type)}</option>)}</select></label><button className="pill primary">Create invitation</button>{message&&<p>{message}</p>}</form>}<SimpleDirectory title="Users and permissions" rows={rows} primary="full_name" secondary="email"/></div>;
}

function OrganizationManager({ rows }: { rows:Row[] }) {
  const router=useRouter();const[open,setOpen]=useState(false);const[message,setMessage]=useState("");
  const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);const response=await fetch("/api/staff/organizations",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(form))});const payload=await response.json() as{error?:string};setMessage(response.ok?"Organization created.":payload.error||"Could not create organization");if(response.ok){setOpen(false);router.refresh();}};
  return <div className="workspace-stack"><button className="workspace-create-card" onClick={()=>setOpen(!open)}><span>＋</span><div><strong>Add a corporate or partner account</strong><small>Set billing, currency and approval ownership</small></div></button>{open&&<form className="workspace-form" onSubmit={submit}><div className="workspace-form-grid"><label>Name<input name="name" required/></label><label>Slug<input name="slug" pattern="[a-z0-9-]+" required/></label><label>Type<select name="type"><option value="corporate">Corporate</option><option value="partner">Partner</option></select></label><label>Status<select name="status"><option>prospect</option><option>active</option><option>suspended</option></select></label><label>Billing email<input type="email" name="billingEmail"/></label><label>Default currency<select name="defaultCurrency"><option>KES</option><option>USD</option></select></label><label className="wide">Travel policy<textarea name="travelPolicy" rows={3}/></label></div><button className="pill primary">Create account</button>{message&&<p>{message}</p>}</form>}<SimpleDirectory title="Corporate and partner accounts" rows={rows} primary="name" secondary="billing_email"/></div>;
}

function PartnerManager({ suppliers, organizations, bookings, assignments }: { suppliers:Row[];organizations:Row[];bookings:Row[];assignments:Row[] }) {
  const router=useRouter();const[mode,setMode]=useState<"supplier"|"assignment"|null>(null);const[message,setMessage]=useState("");
  const submit=async(e:FormEvent<HTMLFormElement>,url:string)=>{e.preventDefault();const response=await fetch(url,{method:"POST",headers:mutationHeaders(url.endsWith("/assignments")),body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});const payload=await response.json() as{error?:string};setMessage(response.ok?"Saved successfully.":payload.error||"Could not save");if(response.ok){setMode(null);router.refresh();}};
  return <div className="workspace-stack"><div className="workspace-admin-actions"><button className="workspace-create-card" onClick={()=>setMode(mode==="supplier"?null:"supplier")}><span>＋</span><div><strong>Add supplier</strong><small>Create a service partner record</small></div></button><button className="workspace-create-card" onClick={()=>setMode(mode==="assignment"?null:"assignment")}><span>✈</span><div><strong>Assign a booking service</strong><small>Send operational work to a partner</small></div></button></div>{mode==="supplier"&&<form className="workspace-form" onSubmit={(event)=>submit(event,"/api/staff/suppliers")}><div className="workspace-form-grid"><label>Name<input name="name" required/></label><label>Category<input name="category" placeholder="Hotel, transfer, guide…" required/></label><label>Partner account<select name="organizationId"><option value="">Independent supplier</option>{organizations.filter((row)=>row.type==="partner").map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.name)}</option>)}</select></label><label>Status<select name="status"><option>pending</option><option>active</option><option>suspended</option></select></label><label>Email<input type="email" name="email"/></label><label>Phone<input name="phone"/></label><label>Country<input name="country"/></label><label className="wide">Notes<textarea name="notes"/></label></div><button className="pill primary">Save supplier</button></form>}{mode==="assignment"&&<form className="workspace-form" onSubmit={(event)=>submit(event,"/api/staff/assignments")}><div className="workspace-form-grid"><label>Booking<select name="bookingId" required><option value="">Choose booking</option>{bookings.map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.booking_number)} · {String(row.destination)}</option>)}</select></label><label>Supplier<select name="supplierId" required><option value="">Choose supplier</option>{suppliers.filter((row)=>row.status==="active").map((row)=><option key={String(row.id)} value={String(row.id)}>{String(row.name)}</option>)}</select></label><label>Service type<input name="serviceType" placeholder="Airport transfer" required/></label><label>Traveler summary<input name="travelerSummary"/></label><label className="wide">Service details<textarea name="serviceDetails" rows={4}/></label></div><button className="pill primary">Create assignment</button></form>}{message&&<p className="workspace-message">{message}</p>}<SimpleDirectory title="Supplier directory" rows={suppliers} primary="name" secondary="category"/><section className="workspace-panel"><PanelHeading title="Service assignments"/><div className="assignment-grid">{assignments.map((row)=><article key={String(row.id)}><small>{String(row.booking_number)} · {String(row.service_type)}</small><h3>{String(row.supplier_name)}</h3><p>{String(row.destination)}</p><Status value={String(row.status)}/></article>)}</div>{assignments.length===0&&<EmptyState title="No partner assignments" text="Assign a confirmed booking service to an active supplier."/>}</section></div>;
}

function Overview({ area, data }: { area: WorkspaceArea; data: WorkspacePayload }) {
  const aggregate=data.overview?.metrics;const metrics = area === "partner" ? [["Active assignments",aggregate?Number(aggregate.active_assignments):data.assignments.filter((r)=>r.status !== "completed").length],["Confirmed",aggregate?Number(aggregate.confirmed_assignments):data.assignments.filter((r)=>r.status === "confirmed").length],["Open updates",aggregate?Number(aggregate.open_support):data.tickets.length],["Documents",aggregate?Number(aggregate.active_bookings):data.bookings.length]] : [["Open requests",aggregate?Number(aggregate.open_requests):data.requests.filter((r)=>!["converted","closed"].includes(String(r.status))).length],["Quotes",aggregate?Number(aggregate.quotes):data.quotes.length],["Active bookings",aggregate?Number(aggregate.active_bookings):data.bookings.filter((r)=>!["completed","cancelled"].includes(String(r.status))).length],["Outstanding invoices",aggregate?Number(aggregate.outstanding_invoices):data.invoices.filter((r)=>!["paid","void"].includes(String(r.status))).length]];
  const latest = data.overview?data.overview.recent.map((row)=>({...row,_type:row.record_type,_date:row.created_at,[String(row.record_type).toLowerCase()+"_number"]:row.reference})):[...data.requests.map((r)=>({...r,_type:"Request",_date:r.created_at})),...data.bookings.map((r)=>({...r,_type:"Booking",_date:r.created_at})),...data.invoices.map((r)=>({...r,_type:"Invoice",_date:r.created_at}))].sort((a,b)=>Number(b._date)-Number(a._date)).slice(0,6);
  return <><section className="workspace-welcome"><div><p>WELCOME BACK</p><h2>{area === "staff" ? "The whole travel operation, in one clear view." : area === "partner" ? "The details your team needs to deliver beautifully." : "Every journey and next step, together."}</h2></div><span>LIVE TVSE WORKSPACE</span></section><div className="workspace-metrics">{metrics.map(([label,value])=><article key={String(label)}><span>{label}</span><strong>{value}</strong><i /></article>)}</div><section className="workspace-panel"><PanelHeading title="Recent activity" action={<Link href={area === "staff"?"/staff/pipeline":`/${area}/requests`}>View all →</Link>} />{latest.length ? <div className="activity-list">{latest.map((row,index)=><div key={`${row._type}-${index}`}><span>{String(row._type).slice(0,1)}</span><div><strong>{displayPrimary(row)}</strong><small>{row._type} · {formatDate(row._date)}</small></div><Status value={String(row.status ?? "active")} /></div>)}</div> : <EmptyState title="Your workspace is ready" text="New travel requests, quotes and bookings will appear here." />}</section></>;
}

function RequestsView({ rows, staff }: { rows: Row[]; staff: boolean }) {
  const [query,setQuery]=useState(""); const visible=rows.filter((row)=>rowMatches(row,query));
  return <section className="workspace-panel"><PanelHeading title={staff?"Travel request pipeline":"Your travel requests"} action={<Link className="pill primary compact" href="/plan-a-trip">New request</Link>} /><TableTools query={query} setQuery={setQuery} count={visible.length} /><div className="workspace-table"><div className="workspace-table-head"><span>Reference</span><span>Journey</span><span>Dates</span><span>Traveler</span><span>Status</span></div>{visible.map((row)=><div className="workspace-table-row" key={String(row.id)}><strong>{String(row.request_number)}</strong><span>{String(row.origin)} → {String(row.destination)}</span><span>{String(row.departure_date)}<small>to {String(row.return_date)}</small></span><span>{String(row.contact_name)}<small>{row.traveler_count} traveler(s)</small></span><Status value={String(row.status)} /></div>)}</div>{visible.length===0&&<EmptyState title="No requests yet" text="Start a travel brief and TVSE will build the next step." />}</section>;
}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function QuotesView({ rows, requests, staff }: { rows: Row[]; requests: Row[]; staff: boolean }) {
  const router=useRouter(); const [busy,setBusy]=useState(""); const [message,setMessage]=useState("");
  const act=async(url:string,body?:unknown)=>{setBusy(url);setMessage("");try{const response=await fetch(url,{method:"POST",headers:mutationHeaders(true),body:JSON.stringify(body??{})});const payload=await response.json() as {error?:string};if(!response.ok)throw new Error(payload.error||"Action failed");router.refresh();}catch(e){setMessage(e instanceof Error?e.message:"Action failed");}finally{setBusy("");}};
  return <div className="workspace-stack">{staff&&<QuoteBuilder requests={requests} onDone={()=>router.refresh()} />}<section className="workspace-panel"><PanelHeading title={staff?"Quotes and proposals":"Your proposals"} />{message&&<p className="workspace-error">{message}</p>}<div className="quote-list">{rows.map((row)=><article key={String(row.id)}><div><small>{String(row.quote_number)} · VERSION {String(row.current_version)}</small><h3>{String(row.destination)}</h3><p>{String(row.departure_date)} to {String(row.return_date)}</p></div><div><strong>{formatMoney(Number(row.total_minor),String(row.currency) as Currency)}</strong><Status value={String(row.status)} /></div><div className="quote-actions">{staff&&row.status==="draft"&&<button disabled={!!busy} onClick={()=>act(`/api/quotes/${row.id}/send`)}>Send proposal</button>}{staff&&row.status==="approved"&&<button disabled={!!busy} onClick={()=>act("/api/bookings",{quoteId:row.id})}>Create booking</button>}{!staff&&["sent","viewed"].includes(String(row.status))&&<><button disabled={!!busy} onClick={()=>act(`/api/quotes/${row.id}/decision`,{decision:"approved"})}>Approve</button><button className="danger" disabled={!!busy} onClick={()=>act(`/api/quotes/${row.id}/decision`,{decision:"declined"})}>Decline</button></>}{row.pdf_key&&<a href={`/api/documents/quote/${row.id}`}>Download PDF</a>}</div></article>)}</div>{rows.length===0&&<EmptyState title="No proposals yet" text={staff?"Build a quote from an approved travel request.":"Your TVSE proposals will appear here for secure review."} />}</section></div>;
}

function QuoteBuilder({ requests, onDone }: { requests: Row[]; onDone: ()=>void }) {
  const [open,setOpen]=useState(false);const[busy,setBusy]=useState(false);const[error,setError]=useState("");const[items,setItems]=useState([{category:"hotel",description:"",quantity:1,unitPrice:"",markup:"0",tax:"0"}]);
  const eligible=requests.filter((r)=>["submitted","qualified","quoting","declined"].includes(String(r.status))&&r.approval_status!=="pending"&&r.approval_status!=="declined");
  const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);setError("");const form=new FormData(e.currentTarget);try{const response=await fetch("/api/quotes",{method:"POST",headers:mutationHeaders(true),body:JSON.stringify({tripRequestId:form.get("tripRequestId"),currency:form.get("currency"),exchangeRate:Number(form.get("exchangeRate")),expiresAt:Date.now()+Number(form.get("validDays"))*86400000,feesMinor:Math.round(Number(form.get("fees")||0)*100),taxMinor:Math.round(Number(form.get("tax")||0)*100),notes:form.get("notes"),items:items.map((item)=>({category:item.category,description:item.description,quantity:item.quantity,unitPriceMinor:Math.round(Number(item.unitPrice||0)*100),markupMinor:Math.round(Number(item.markup||0)*100),taxMinor:Math.round(Number(item.tax||0)*100)}))})});const payload=await response.json() as {error?:string};if(!response.ok)throw new Error(payload.error||"Could not create quote");setOpen(false);onDone();}catch(cause){setError(cause instanceof Error?cause.message:"Could not create quote");}finally{setBusy(false);}};
  if(!open)return <button className="workspace-create-card" onClick={()=>setOpen(true)}><span>＋</span><div><strong>Build a new travel proposal</strong><small>Versioned pricing, fees, taxes and PDF output</small></div></button>;
  return <form className="workspace-form quote-builder" onSubmit={submit}><PanelHeading title="New proposal" action={<button type="button" onClick={()=>setOpen(false)}>Close</button>} /><div className="workspace-form-grid"><label>Travel request<select name="tripRequestId" required><option value="">Choose a request</option>{eligible.map((r)=><option key={String(r.id)} value={String(r.id)}>{String(r.request_number)} · {String(r.destination)}</option>)}</select></label><label>Currency<select name="currency"><option>KES</option><option>USD</option></select></label><label>Exchange rate<input name="exchangeRate" type="number" step="0.0001" min="0.0001" defaultValue="1" required /></label><label>Valid for days<input name="validDays" type="number" min="1" defaultValue="14" required /></label><label>TVSE fees<input name="fees" type="number" min="0" defaultValue="0" /></label><label>Additional tax<input name="tax" type="number" min="0" defaultValue="0" /></label></div><h3>Proposal items</h3>{items.map((item,index)=><div className="quote-item-editor" key={index}><select value={item.category} onChange={(e)=>setItems((all)=>all.map((row,i)=>i===index?{...row,category:e.target.value}:row))}><option>flight</option><option>hotel</option><option>transfer</option><option>activity</option><option>visa</option><option>insurance</option><option>fee</option><option>other</option></select><input placeholder="Description" value={item.description} required onChange={(e)=>setItems((all)=>all.map((row,i)=>i===index?{...row,description:e.target.value}:row))}/><input aria-label="Quantity" type="number" min="1" value={item.quantity} onChange={(e)=>setItems((all)=>all.map((row,i)=>i===index?{...row,quantity:Number(e.target.value)}:row))}/><input aria-label="Unit price" type="number" min="0" placeholder="Unit price" value={item.unitPrice} required onChange={(e)=>setItems((all)=>all.map((row,i)=>i===index?{...row,unitPrice:e.target.value}:row))}/><button type="button" aria-label="Remove item" onClick={()=>setItems((all)=>all.filter((_,i)=>i!==index))}>×</button></div>)}<button className="text-action" type="button" onClick={()=>setItems((all)=>[...all,{category:"activity",description:"",quantity:1,unitPrice:"",markup:"0",tax:"0"}])}>+ Add another item</button><label>Proposal notes<textarea name="notes" rows={3}/></label>{error&&<p className="workspace-error">{error}</p>}<button className="pill primary" disabled={busy||eligible.length===0}>{busy?"Building…":"Create proposal"}</button></form>;
}

function BookingsView({ rows, staff }: { rows: Row[]; staff: boolean }) { return <section className="workspace-panel"><PanelHeading title={staff?"Booking operations":"Your confirmed journeys"} /><div className="booking-grid">{rows.map((row)=><article key={String(row.id)}><small>{String(row.booking_number)}</small><h3>{String(row.destination)}</h3><p>{String(row.departure_date)} → {String(row.return_date)}</p><div><Status value={String(row.status)} /><span>{String(row.traveler_count)} travelers</span></div>{row.itinerary_pdf_key&&<a href={`/api/documents/booking/${row.id}`}>Download itinerary →</a>}</article>)}</div>{rows.length===0&&<EmptyState title="No bookings yet" text="Approved proposals become operational bookings here." />}</section>; }

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function InvoicesView({ invoices, bookings, staff, actor }: { invoices: Row[]; bookings: Row[]; staff: boolean; actor: Actor }) {
  const router=useRouter();const[message,setMessage]=useState("");const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);const response=await fetch("/api/invoices",{method:"POST",headers:mutationHeaders(true),body:JSON.stringify({bookingId:form.get("bookingId"),dueDate:form.get("dueDate"),taxMinor:Math.round(Number(form.get("tax")||0)*100)})});const payload=await response.json() as {error?:string};setMessage(response.ok?"Invoice issued.":payload.error||"Could not issue invoice");if(response.ok)router.refresh();};
  return <div className="workspace-stack">{staff&&["owner","admin","finance"].includes(actor.role)&&<form className="workspace-form inline-finance-form" onSubmit={submit}><h2>Issue an invoice</h2><label>Booking<select name="bookingId" required><option value="">Choose booking</option>{bookings.map((r)=><option key={String(r.id)} value={String(r.id)}>{String(r.booking_number)} · {String(r.destination)}</option>)}</select></label><label>Due date<input type="date" name="dueDate" required /></label><label>Additional tax<input type="number" min="0" name="tax" defaultValue="0" /></label><button className="pill primary compact">Issue</button>{message&&<p>{message}</p>}</form>}<section className="workspace-panel"><PanelHeading title={staff?"Invoices and recorded payments":"Invoices"} /><div className="invoice-list">{invoices.map((row)=><InvoiceCard key={String(row.id)} row={row} staff={staff&&["owner","admin","finance"].includes(actor.role)} onDone={()=>router.refresh()} />)}</div>{invoices.length===0&&<EmptyState title="No invoices yet" text="Issued invoices and payment balances will appear here." />}</section></div>;
}

function InvoiceCard({ row, staff, onDone }: { row: Row; staff: boolean; onDone:()=>void }) { const[open,setOpen]=useState(false);const[error,setError]=useState("");const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);const response=await fetch(`/api/invoices/${row.id}/payments`,{method:"POST",headers:mutationHeaders(true),body:JSON.stringify({amountMinor:Math.round(Number(form.get("amount"))*100),currency:row.currency,method:form.get("method"),reference:form.get("reference")})});const payload=await response.json() as{error?:string};if(!response.ok)return setError(payload.error||"Could not record payment");setOpen(false);onDone();};return <article><div><small>{String(row.invoice_number)} · {String(row.booking_number)}</small><h3>{String(row.destination)}</h3><Status value={String(row.status)} /></div><div className="invoice-money"><span>Total<strong>{formatMoney(Number(row.total_minor),String(row.currency) as Currency)}</strong></span><span>Paid<strong>{formatMoney(Number(row.paid_minor),String(row.currency) as Currency)}</strong></span><span>Due<strong>{formatMoney(Number(row.due_minor),String(row.currency) as Currency)}</strong></span></div><div className="invoice-actions">{row.pdf_key&&<a href={`/api/documents/invoice/${row.id}`}>Download invoice</a>}{staff&&!['paid','void'].includes(String(row.status))&&<button onClick={()=>setOpen(!open)}>Record payment</button>}</div>{open&&<form onSubmit={submit} className="payment-form"><input name="amount" type="number" min="0.01" step="0.01" placeholder="Amount" required/><select name="method"><option value="bank_transfer">Bank transfer</option><option value="cash">Cash</option><option value="external_link">External link</option><option value="mobile_money">Mobile money</option><option value="card">Card</option><option value="other">Other</option></select><input name="reference" placeholder="Reference (required unless cash)"/><button>Save payment</button>{error&&<p>{error}</p>}</form>}</article>;}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function SupportView({ rows, bookings, staff }: { rows: Row[]; bookings: Row[]; staff: boolean }) {
  const router=useRouter();const[message,setMessage]=useState("");const[selected,setSelected]=useState("");const[conversation,setConversation]=useState<{ticket:Row;messages:Row[]}|null>(null);
  const open=async(id:string)=>{setSelected(id);setMessage("");const response=await fetch(`/api/support/${id}`);const payload=await response.json() as{data?:{ticket:Row;messages:Row[]};error?:string};if(response.ok&&payload.data)setConversation(payload.data);else setMessage(payload.error||"Could not open conversation");};
  const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);const response=await fetch("/api/support",{method:"POST",headers:mutationHeaders(),body:JSON.stringify({bookingId:form.get("bookingId")||undefined,subject:form.get("subject"),priority:form.get("priority"),message:form.get("message")})});const payload=await response.json() as{error?:string};setMessage(response.ok?"Support request opened.":payload.error||"Could not open request");if(response.ok){e.currentTarget.reset();router.refresh();}};
  const reply=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);const response=await fetch(`/api/support/${selected}/messages`,{method:"POST",headers:mutationHeaders(),body:JSON.stringify({message:form.get("message"),internal:staff&&form.get("internal")==="on"})});const payload=await response.json() as{error?:string};if(!response.ok)return setMessage(payload.error||"Could not send message");e.currentTarget.reset();await open(selected);router.refresh();};
  const changeStatus=async(status:string)=>{const response=await fetch(`/api/support/${selected}`,{method:"PATCH",headers:mutationHeaders(),body:JSON.stringify({status})});const payload=await response.json() as{error?:string};if(!response.ok)return setMessage(payload.error||"Could not update support request");await open(selected);router.refresh();};
  return <div className="workspace-stack">{!staff&&<form className="workspace-form support-form" onSubmit={submit}><h2>Ask TVSE for help</h2><div><label>Booking<select name="bookingId"><option value="">General question</option>{bookings.map((booking)=><option value={String(booking.id)} key={String(booking.id)}>{String(booking.booking_number)} · {String(booking.destination)}</option>)}</select></label><label>Subject<input name="subject" required /></label><label>Priority<select name="priority"><option>normal</option><option>high</option><option>urgent</option><option>low</option></select></label></div><label>What happened?<textarea name="message" rows={4} required /></label><button className="pill primary">Open support request</button>{message&&<p>{message}</p>}</form>}<section className="workspace-panel"><PanelHeading title={staff?"Traveler support inbox":"Your support requests"}/>{message&&<p className="workspace-message">{message}</p>}<div className="ticket-list">{rows.map((row)=><article key={String(row.id)}><span>{String(row.ticket_number)}</span><div><h3>{String(row.subject)}</h3><p>{String(row.latest_message||"")}</p></div><div><Status value={String(row.status)}/><small>{String(row.priority)}</small><button onClick={()=>open(String(row.id))}>Open</button></div></article>)}</div>{rows.length===0&&<EmptyState title="No support requests" text="When you need help, your conversation with TVSE will stay organized here."/>}</section>{conversation&&<section className="workspace-panel support-conversation"><PanelHeading title={String(conversation.ticket.subject)} action={<button onClick={()=>{setConversation(null);setSelected("");}}>Close</button>}/>{staff&&<label>Status<select value={String(conversation.ticket.status)} onChange={(event)=>changeStatus(event.target.value)}><option>open</option><option>waiting_customer</option><option>waiting_tvse</option><option>resolved</option><option>closed</option></select></label>}<div className="support-thread">{conversation.messages.map((item)=><article key={String(item.id)} className={item.internal?"is-internal":""}><strong>{String(item.sender_name||item.sender_email||"TVSE traveler")}</strong><p>{String(item.body)}</p><small>{formatDate(item.created_at)}{item.internal?" · Internal note":""}</small></article>)}</div><form className="payment-form" onSubmit={reply}><textarea name="message" rows={3} placeholder={staff?"Reply to the traveler or add an internal note":"Reply to TVSE"} required/>{staff&&<label><input type="checkbox" name="internal"/> Internal note</label>}<button>Send message</button></form></section>}</div>;
}

function ApprovalsView({ rows }: { rows: Row[] }) { const router=useRouter();const act=async(id:string,decision:string)=>{await fetch(`/api/trip-requests/${id}/approval`,{method:"POST",headers:mutationHeaders(true),body:JSON.stringify({decision})});router.refresh();};return <section className="workspace-panel"><PanelHeading title="Travel approvals"/><div className="approval-list">{rows.map((row)=><article key={String(row.id)}><div><small>{String(row.request_number)}</small><h3>{String(row.destination)}</h3><p>{String(row.departure_date)} to {String(row.return_date)} · {formatMoney(Number(row.budget_minor),String(row.currency) as Currency)} budget</p></div><Status value={String(row.status)}/>{row.status==="pending"&&<div><button onClick={()=>act(String(row.entity_id),"approved")}>Approve</button><button className="danger" onClick={()=>act(String(row.entity_id),"declined")}>Decline</button></div>}</article>)}</div>{rows.length===0&&<EmptyState title="Nothing waiting for approval" text="Company requests assigned to you will appear here."/>}</section>;}

function AssignmentsView({ rows }: { rows: Row[] }) { const router=useRouter();const act=async(id:string,status:string)=>{await fetch(`/api/assignments/${id}`,{method:"PATCH",headers:mutationHeaders(true),body:JSON.stringify({status})});router.refresh();};return <section className="workspace-panel"><PanelHeading title="Assigned travel services"/><div className="assignment-grid">{rows.map((row)=><article key={String(row.id)}><small>{String(row.booking_number)} · {String(row.service_type)}</small><h3>{String(row.destination)}</h3><p>{String(row.traveler_summary||"Traveler details are supplied only as required for this service.")}</p><Status value={String(row.status)}/>{row.status==="assigned"&&<div><button onClick={()=>act(String(row.id),"confirmed")}>Confirm</button><button className="danger" onClick={()=>act(String(row.id),"declined")}>Decline</button></div>}{row.status==="confirmed"&&<button onClick={()=>act(String(row.id),"completed")}>Mark complete</button>}</article>)}</div>{rows.length===0&&<EmptyState title="No assignments yet" text="New booking services assigned to your partner account will appear here."/>}</section>;}

function DocumentsView({ data }: { data: WorkspacePayload }) { const docs=[...data.quotes.filter(r=>r.pdf_key).map(r=>({type:"Quote",reference:r.quote_number,id:r.id,url:`/api/documents/quote/${r.id}`})),...data.bookings.filter(r=>r.itinerary_pdf_key).map(r=>({type:"Itinerary",reference:r.booking_number,id:r.id,url:`/api/documents/booking/${r.id}`})),...data.invoices.filter(r=>r.pdf_key).map(r=>({type:"Invoice",reference:r.invoice_number,id:r.id,url:`/api/documents/invoice/${r.id}`}))];return <section className="workspace-panel"><PanelHeading title="Travel documents"/><div className="document-list">{docs.map(doc=><a href={String(doc.url)} key={`${doc.type}-${doc.id}`}><span>PDF</span><div><strong>{String(doc.type)}</strong><small>{String(doc.reference)}</small></div><b>↓</b></a>)}</div>{docs.length===0&&<EmptyState title="No documents yet" text="Issued proposals, itineraries and invoices will be available here."/>}</section>;}

function UsersView({ rows, staff }: { rows: Row[]; staff: boolean }) { const router=useRouter();const[open,setOpen]=useState(false);const[message,setMessage]=useState("");const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);const response=await fetch("/api/staff/users",{method:"POST",headers:mutationHeaders(true),body:JSON.stringify({email:form.get("email"),fullName:form.get("fullName"),role:form.get("role")})});const payload=await response.json() as{error?:string};setMessage(response.ok?"Invitation created.":payload.error||"Could not invite user");if(response.ok){setOpen(false);router.refresh();}};return <div className="workspace-stack">{staff&&<button className="workspace-create-card" onClick={()=>setOpen(!open)}><span>＋</span><div><strong>Invite a user</strong><small>Assign a protected TVSE role</small></div></button>}{open&&<form className="workspace-form user-invite-form" onSubmit={submit}><label>Full name<input name="fullName" required/></label><label>Email<input type="email" name="email" required/></label><label>Role<select name="role"><option value="agent">Travel agent</option><option value="finance">Finance</option><option value="content">Content</option><option value="admin">Administrator</option><option value="corporate_requester">Corporate requester</option><option value="corporate_approver">Corporate approver</option><option value="partner">Partner</option></select></label><button className="pill primary">Create invitation</button>{message&&<p>{message}</p>}</form>}<section className="workspace-panel"><PanelHeading title={staff?"Users and permissions":"Company travelers"}/><div className="user-list">{rows.map((row)=><div key={String(row.id)}><span>{String(row.full_name||row.email).slice(0,1).toUpperCase()}</span><div><strong>{String(row.full_name||row.email)}</strong><small>{String(row.email)}</small></div><Status value={String(row.role||row.membership_role)}/><small>{String(row.status||"active")}</small></div>)}</div>{rows.length===0&&<EmptyState title="No users yet" text="Invited users and company travelers will appear here."/>}</section></div>;}

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function ContentStudio({ rows }: { rows: Row[] }) {
  const router=useRouter();const[editing,setEditing]=useState<Row|null>(null);const[open,setOpen]=useState(false);const[message,setMessage]=useState("");const[preview,setPreview]=useState<Row|null>(null);
  const edit=async(row?:Row)=>{setMessage("");if(!row){setEditing(null);setPreview(null);setOpen(true);return;}const response=await fetch(`/api/content/${row.id}`);const payload=await response.json() as{data?:Row;error?:string};if(!response.ok||!payload.data){setMessage(payload.error||"Could not load content");return;}setEditing(payload.data);setPreview(payload.data);setOpen(true);};
  const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const form=new FormData(e.currentTarget);const kind=String(form.get("kind"));const body={kind,slug:form.get("slug"),title:form.get("title"),summary:form.get("summary"),description:form.get("description"),imagePath:form.get("imagePath"),status:form.get("status"),country:kind==="destination"?form.get("country"):undefined,region:kind==="destination"?form.get("region"):undefined,durationDays:kind==="package"?Number(form.get("durationDays")):undefined,fromPriceMinor:kind==="package"?Math.round(Number(form.get("price")||0)*100):undefined,currency:kind==="package"?form.get("currency"):undefined,seoTitle:form.get("seoTitle")||undefined,seoDescription:form.get("seoDescription")||undefined};const url=editing?.id?`/api/content/${editing.id}`:"/api/content";const response=await fetch(url,{method:editing?.id?"PATCH":"POST",headers:mutationHeaders(),body:JSON.stringify(body)});const payload=await response.json() as{data?:{id?:string};error?:string};if(!response.ok){setMessage(payload.error||"Could not save content");return;}const contentId=String(payload.data?.id||editing?.id||"");const file=form.get("imageFile");if(file instanceof File&&file.size>0&&contentId){const upload=new FormData();upload.set("file",file);upload.set("entityType","content");upload.set("entityId",contentId);upload.set("visibility","public");const uploaded=await fetch("/api/uploads",{method:"POST",body:upload});const asset=await uploaded.json() as{data?:{id?:string};error?:string};if(!uploaded.ok||!asset.data?.id){setMessage(asset.error||"Content saved, but the image upload failed");router.refresh();return;}await fetch(`/api/content/${contentId}`,{method:"PATCH",headers:mutationHeaders(),body:JSON.stringify({...body,imagePath:`/api/uploads/${asset.data.id}`})});}setMessage("Content saved.");setOpen(false);setEditing(null);router.refresh();};
  const defaults=editing||{};
  return <div className="workspace-stack"><button className="workspace-create-card" onClick={()=>open?setOpen(false):edit()}><span>＋</span><div><strong>Create destination, package or story</strong><small>Draft, review and publish from TVSE</small></div></button>{open&&<form key={String(editing?.id||"new")} className="workspace-form content-form" onSubmit={submit} onInput={(event)=>{const form=new FormData(event.currentTarget);setPreview({title:String(form.get("title")||"Untitled"),summary:String(form.get("summary")||""),image_path:String(form.get("imagePath")||"")});}}><PanelHeading title={editing?`Edit ${String(editing.title)}`:"New content"} action={<button type="button" onClick={()=>setOpen(false)}>Close</button>}/><div className="workspace-form-grid"><label>Content type<select name="kind" defaultValue={String(defaults.kind||"destination")}><option value="destination">Destination</option><option value="package">Package</option><option value="article">Article</option><option value="guide">Guide</option></select></label><label>Status<select name="status" defaultValue={String(defaults.status||"draft")}><option>draft</option><option>published</option><option>archived</option></select></label><label>Title<input name="title" defaultValue={String(defaults.title||"")} required/></label><label>Slug<input name="slug" pattern="[a-z0-9-]+" defaultValue={String(defaults.slug||"")} required/></label><label>Country<input name="country" defaultValue={String(defaults.country||"")}/></label><label>Region<input name="region" defaultValue={String(defaults.region||"")}/></label><label>Duration days<input name="durationDays" type="number" min="1" defaultValue={Number(defaults.duration_days||7)}/></label><label>From price<input name="price" type="number" min="0" defaultValue={Number(defaults.from_price_minor||0)/100}/></label><label>Currency<select name="currency" defaultValue={String(defaults.currency||"KES")}><option>KES</option><option>USD</option></select></label><label>Current image path<input name="imagePath" defaultValue={String(defaults.image_path||"/hero-zanzibar.jpg")} required/></label><label>Upload image<input name="imageFile" type="file" accept="image/jpeg,image/png,image/webp"/></label><label>SEO title<input name="seoTitle" defaultValue={String(defaults.seo_title||"")}/></label><label className="wide">SEO description<textarea name="seoDescription" rows={2} defaultValue={String(defaults.seo_description||"")}/></label><label className="wide">Summary<textarea name="summary" rows={2} defaultValue={String(defaults.summary||"")} required/></label><label className="wide">Description<textarea name="description" rows={7} defaultValue={String(defaults.description||"")} required/></label></div>{preview&&<aside className="content-preview"><small>LIVE PREVIEW</small><h3>{String(preview.title||"Untitled")}</h3><p>{String(preview.summary||"Add a concise summary for search and cards.")}</p></aside>}<button className="pill primary">Save content</button>{message&&<p>{message}</p>}</form>}<section className="workspace-panel"><PanelHeading title="Publishing library"/><div className="content-list">{rows.map((row)=><div key={String(row.id)}><span>{String(row.kind).slice(0,1).toUpperCase()}</span><div><strong>{String(row.title)}</strong><small>/{String(row.slug)} · {String(row.kind)}</small></div><Status value={String(row.status)}/><time>{formatDate(row.updated_at)}</time><button onClick={()=>edit(row)}>Edit</button>{row.status==="published"&&<a href={row.kind==="destination"?`/destinations/${row.slug}`:row.kind==="package"?`/packages/${row.slug}`:row.kind==="article"?`/resources/blog/${row.slug}`:`/resources/guides/${row.slug}`} target="_blank">View</a>}</div>)}</div></section></div>;
}

function SimpleDirectory({ title, rows, primary, secondary }: { title:string; rows:Row[];primary:string;secondary:string }) { const[query,setQuery]=useState("");const visible=rows.filter(row=>rowMatches(row,query));return <section className="workspace-panel"><PanelHeading title={title}/><TableTools query={query} setQuery={setQuery} count={visible.length}/><div className="directory-grid">{visible.map(row=><article key={String(row.id)}><span>{String(row[primary]||"T").slice(0,1)}</span><h3>{String(row[primary]||"Untitled")}</h3><p>{String(row[secondary]||"")}</p><Status value={String(row.status||"active")}/></article>)}</div>{visible.length===0&&<EmptyState title="No records yet" text="New records will appear here."/>}</section>;}
function ActivityView({ rows }: { rows:Row[] }) { return <section className="workspace-panel"><PanelHeading title="Immutable activity history"/><div className="audit-list">{rows.map(row=><div key={String(row.id)}><time>{formatDate(row.created_at)}</time><strong>{String(row.action).replaceAll("_"," ")}</strong><span>{String(row.entity_type)} · {String(row.entity_id)}</span><small>{String(row.actor_email||"system")}</small></div>)}</div>{rows.length===0&&<EmptyState title="No activity yet" text="Protected administrative actions will be recorded here."/>}</section>;}
function NotificationOutbox({rows}:{rows:Row[]}){const router=useRouter();const[message,setMessage]=useState("");const retry=async(id:string)=>{const response=await fetch(`/api/notifications/${id}/retry`,{method:"POST",headers:mutationHeaders(true)});const payload=await response.json() as{error?:string};setMessage(response.ok?"Email queued successfully.":payload.error||"Could not retry email");if(response.ok)router.refresh();};return <section className="workspace-panel"><PanelHeading title="Transactional email outbox"/>{message&&<p className="workspace-message">{message}</p>}<div className="audit-list">{rows.map((row)=><div key={String(row.id)}><time>{formatDate(row.created_at)}</time><strong>{String(row.template).replaceAll("_"," ")}</strong><span>{String(row.destination)}</span><Status value={String(row.status)}/>{["pending","failed"].includes(String(row.status))&&<button onClick={()=>retry(String(row.id))}>Retry</button>}</div>)}</div>{rows.length===0&&<EmptyState title="No email activity" text="Transactional email delivery will appear here."/>}</section>;}
function ReportsView({ data }: { data:WorkspacePayload }) { const report=data.report??{pipeline:[],finance:[],totals:{bookings:0,open_support:0}};const requestCount=report.pipeline.reduce((sum,row)=>sum+Number(row.count||0),0);const collectedLabel=report.finance.map((row)=>formatMoney(Number(row.paid_minor||0),String(row.currency||"KES") as Currency)).join(" · ")||formatMoney(0,"KES");return <div className="workspace-stack"><div className="workspace-metrics"><article><span>Travel requests</span><strong>{requestCount}</strong><i/></article><article><span>Bookings</span><strong>{Number(report.totals.bookings||0)}</strong><i/></article><article><span>Collected by currency</span><strong className="money-metric">{collectedLabel}</strong><i/></article><article><span>Open support</span><strong>{Number(report.totals.open_support||0)}</strong><i/></article></div><section className="workspace-panel"><PanelHeading title="Request pipeline"/><div className="report-bars">{report.pipeline.map((row)=><div key={String(row.status)}><span>{String(row.status).replaceAll("_"," ")}</span><i><b style={{width:`${Math.max(8,(Number(row.count||0)/Math.max(1,requestCount))*100)}%`}}/></i><strong>{Number(row.count||0)}</strong></div>)}</div></section></div>;}
function SettingsView({ actor, organization, area }: { actor:Actor;organization?:Row|null;area:WorkspaceArea }) { return <div className="settings-grid"><section className="workspace-panel"><PanelHeading title={area==="staff"?"Your staff account":"Profile and account"}/><dl className="settings-list"><div><dt>Name</dt><dd>{actor.fullName||"Not supplied"}</dd></div><div><dt>Email</dt><dd>{actor.email}</dd></div><div><dt>Role</dt><dd>{actor.role.replaceAll("_"," ")}</dd></div><div><dt>Authentication</dt><dd>{actor.source==="platform"?"Platform sign-in":"Secure email link"}</dd></div></dl></section>{organization&&<section className="workspace-panel"><PanelHeading title="Organization"/><dl className="settings-list"><div><dt>Name</dt><dd>{String(organization.name)}</dd></div><div><dt>Type</dt><dd>{String(organization.type)}</dd></div><div><dt>Currency</dt><dd>{String(organization.default_currency)}</dd></div><div><dt>Status</dt><dd>{String(organization.status)}</dd></div></dl></section>}</div>;}

function PanelHeading({ title, action }: { title:string;action?:ReactNode }) { return <div className="workspace-panel-heading"><h2>{title}</h2>{action}</div>; }
function TableTools({query,setQuery,count}:{query:string;setQuery:(v:string)=>void;count:number}){const router=useRouter();const pathname=usePathname();const searchParams=useSearchParams();const[draft,setDraft]=useState(()=>searchParams.get("q")??query);useEffect(()=>setQuery(draft),[draft,setQuery]);useEffect(()=>{const current=searchParams.get("q")??"";if(current===draft)return;const timer=setTimeout(()=>{const params=new URLSearchParams(searchParams.toString());if(draft.trim())params.set("q",draft.trim());else params.delete("q");params.delete("cursor");router.replace(`${pathname}${params.size?`?${params}`:""}`,{scroll:false});},250);return()=>clearTimeout(timer);},[draft,pathname,router,searchParams]);return <div className="table-tools"><label>Search<input value={draft} onChange={event=>setDraft(event.target.value)} placeholder="Search records"/></label><span>{count} records</span></div>;}
function Status({ value }: { value:string }) { const tone=["approved","paid","confirmed","completed","active","published","delivered"].includes(value)?"good":["declined","cancelled","void","failed","bounced","suspended"].includes(value)?"bad":["pending","draft","submitted","quoted","issued","open","sent"].includes(value)?"wait":"neutral";return <span className={`status-pill ${tone}`}>{value.replaceAll("_"," ")}</span>; }
function EmptyState({title,text}:{title:string;text:string}){return <div className="workspace-empty"><span>✈</span><h3>{title}</h3><p>{text}</p></div>;}
function displayPrimary(row:Row){return String(row.request_number||row.booking_number||row.invoice_number||row.destination||"TVSE update");}
function formatDate(value:unknown){if(!value)return "—";const number=Number(value);return new Date(Number.isFinite(number)?number:String(value)).toLocaleDateString("en-KE",{day:"numeric",month:"short",year:"numeric"});}
function rowMatches(row:Row,query:string){const term=query.trim().toLowerCase();if(!term)return true;return [row.request_number,row.quote_number,row.booking_number,row.invoice_number,row.ticket_number,row.destination,row.title,row.subject,row.status,row.role,row.type,row.kind,row.email,row.name,row.company].some((value)=>String(value??"").toLowerCase().includes(term));}
